def coins(S): return [(z,y,S-5*z-2*y) for z in range(S//5,-1,-1) for y in range((S-5*z)//2,-1,-1)]
def eq(S): return sum(1 for z in range(S//5+1) for y in range((S-5*z)//2+1))
